package org.apache.commons.jxpath.ri.compiler;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import org.apache.commons.jxpath.ri.EvalContext;
import org.junit.Test;

public class ComputeValueTests {

    private static class ConstantExpression extends Expression {
        private final Object value;
        private final boolean throwOnCompute;
        private int computeCount;

        ConstantExpression(final Object value) {
            this.value = value;
            this.throwOnCompute = false;
        }

        ConstantExpression(final RuntimeException ex) {
            this.value = ex;
            this.throwOnCompute = true;
        }

        @Override
        public Object computeValue(final EvalContext context) {
            computeCount++;
            if (throwOnCompute) {
                throw (RuntimeException) value;
            }
            return value;
        }

        @Override
        public boolean computeContextDependent() {
            return false;
        }

        @Override
        public String getSymbol() {
            return "const";
        }

        @Override
        public Expression[] getParameters() {
            return new Expression[0];
        }

        @Override
        public Object compute(final EvalContext context) {
            return computeValue(context);
        }

        int getComputeCount() {
            return computeCount;
        }
    }

    @Test
    public void testBasicModuloWithPositiveIntegers() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(5), new ConstantExpression(2));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(1.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testTruncatesFractionalResultTowardZero() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(5), new ConstantExpression(2.5));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(0.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testNegativeDividendProducesNegativeTruncatedResult() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(-5), new ConstantExpression(2));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(-1.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testNegativeDivisorPreservesJavaRemainderSemanticsAfterCast() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(5), new ConstantExpression(-2));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(1.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testUsesBothOperandsExactlyOnce() {
        ConstantExpression left = new ConstantExpression(10);
        ConstantExpression right = new ConstantExpression(3);
        CoreOperationMod op = new CoreOperationMod(left, right);

        Object result = op.computeValue(null);

        assertTrue(result instanceof Double);
        assertEquals(1.0, ((Double) result).doubleValue(), 0.0);
        assertEquals(1, left.getComputeCount());
        assertEquals(1, right.getComputeCount());
    }

    @Test
    public void testNullLeftOperandTreatedAsZero() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(null), new ConstantExpression(3));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(0.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testNullRightOperandYieldsNaNConvertedToZeroLongResult() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(5), new ConstantExpression(null));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(0.0, ((Double) result).doubleValue(), 0.0);
    }

    @Test
    public void testDivisionByZeroThrowsArithmeticExceptionForInfiniteRemainderCast() {
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(5), new ConstantExpression(0));
        try {
            op.computeValue(null);
            fail("Expected ArithmeticException");
        } catch (ArithmeticException expected) {
            // expected
        }
    }

    @Test
    public void testOperandExceptionIsPropagated() {
        RuntimeException boom = new RuntimeException("boom");
        CoreOperationMod op = new CoreOperationMod(new ConstantExpression(1), new ConstantExpression(boom));
        try {
            op.computeValue(null);
            fail("Expected RuntimeException");
        } catch (RuntimeException ex) {
            assertTrue(ex == boom);
        }
    }

    @Test
    public void testLargeValuesStillFollowCastAfterRemainder() {
        CoreOperationMod op = new CoreOperationMod(
                new ConstantExpression(9_223_372_036_854_775_000d),
                new ConstantExpression(10d));
        Object result = op.computeValue(null);
        assertTrue(result instanceof Double);
        assertEquals(0.0, ((Double) result).doubleValue(), 0.0);
    }
}

