    @Test
    public void testSameNodeInstanceReturnsZero() {
        Attribute attr = new Attribute("attr", "value");
        NodePointer pointer1 = new JDOMNodePointer(attr, null);
        NodePointer pointer2 = pointer1;

        int result = parentPointer.compareChildNodePointers(pointer1, pointer2);
        assertEquals("Same instance should return 0", 0, result);
    }

    @Test
    public void testAttributeVsChildNode() {
        Attribute attr = new Attribute("attr", "value");
        Text text = new Text("text");
        parentElement.setAttribute(attr);
        parentElement.addContent(text);

        NodePointer attrPointer = new JDOMNodePointer(attr, null);
        NodePointer textPointer = new JDOMNodePointer(text, null);

        int result = parentPointer.compareChildNodePointers(attrPointer, textPointer);
        assertTrue("Attribute should precede child node", result < 0);

        result = parentPointer.compareChildNodePointers(textPointer, attrPointer);
        assertTrue("Child node should follow attribute", result > 0);
    }

