        for (int i = 0; i < 10000; i++) {
            sb.append("a");
        }
        String longString = sb.toString();
        mockStream = new SimpleCharStream(new StringReader(longString));
        tokenManager = new XPathParserTokenManager(mockStream);

        Token token = tokenManager.jjFillToken();

        assertNotNull(token);
        assertEquals(longString, token.image);
        assertPositionInfoSet(token);
    }

    @Test
    public void testTokenWithMixedContent() {
