        mockStream = new SimpleCharStream(new StringReader("additional"));
        tokenManager = new XPathParserTokenManager(mockStream);

        Token token = tokenManager.jjFillToken();

        assertNotNull(token);
        assertEquals(8, token.kind);
        assertEquals("|", token.image); // Should use literal image, not stream
        assertPositionInfoSet(token);
    }

    private void assertPositionInfoSet(Token token) {
        assertTrue(token.beginLine >= 0);
        assertTrue(token.beginColumn >= 0);
        assertTrue(token.endLine >= 0);
        assertTrue(token.endColumn >= 0);
    }
}

