package org.apache.commons.jxpath.ri.model.jdom;

import org.jdom.CDATA;
import org.jdom.Content;
import org.jdom.Element;
import org.jdom.Namespace;
import org.jdom.ProcessingInstruction;
import org.jdom.Text;
import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Method;
import java.util.Locale;

public class AsPathTests {

    private static JDOMNodePointer pointer(Object node) {
        return new JDOMNodePointer(node, Locale.US);
    }

    private static JDOMNodePointer pointer(Object node, String id) {
        return new JDOMNodePointer(node, Locale.US, id);
    }

    private static void setParent(JDOMNodePointer child, JDOMNodePointer parent) {
        try {
            Method m = org.apache.commons.jxpath.ri.model.NodePointer.class.getDeclaredMethod(
                    "setParent",
                    org.apache.commons.jxpath.ri.model.NodePointer.class
            );
            m.setAccessible(true);
            m.invoke(child, parent);
        } catch (NoSuchMethodException e) {
            try {
                java.lang.reflect.Field f = org.apache.commons.jxpath.ri.model.NodePointer.class.getDeclaredField("parent");
                f.setAccessible(true);
                f.set(child, parent);
            } catch (Exception ex) {
                throw new AssertionError(ex);
            }
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static Element element(String name) {
        return new Element(name);
    }

    private static Element namespacedElement(String name, String prefix, String uri) {
        return new Element(name, Namespace.getNamespace(prefix, uri));
    }

    private static ProcessingInstruction pi(String target, String data) {
        return new ProcessingInstruction(target, data);
    }

    @Test
    public void idTakesPrecedenceAndEscapesQuotes() {
        Element node = element("root");
        JDOMNodePointer p = pointer(node, "a'b\"c");

        Assert.assertEquals("id('a\\'b\"c')", p.asPath());
    }

    @Test
    public void rootElementWithoutParentProducesRelativeElementPath() {
        Element node = element("root");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("root[1]", p.asPath());
    }

    @Test
    public void childElementAppendsToParentPathWithSlash() {
        Element parentNode = element("parent");
        JDOMNodePointer parent = pointer(parentNode);

        Element childNode = element("child");
        JDOMNodePointer child = pointer(childNode);
        setParent(child, parent);

        Assert.assertEquals("parent[1]/child[1]", child.asPath());
    }

    @Test
    public void namespacedElementWithKnownPrefixUsesPrefixedQName() {
        Element node = namespacedElement("child", "p", "urn:test");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("p:child[1]", p.asPath());
    }

    @Test
    public void namespacedElementWithoutPrefixFallsBackToNodeTest() {
        Element node = namespacedElement("child", "", "urn:test");
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("node()[1]", p.asPath());
    }

    @Test
    public void textNodeProducesTextPath() {
        Text text = new Text("value");
        JDOMNodePointer p = pointer(text);

        Assert.assertEquals("/text()[1]", p.asPath());
    }

    @Test
    public void cdataNodeProducesTextPath() {
        CDATA cdata = new CDATA("value");
        JDOMNodePointer p = pointer(cdata);

        Assert.assertEquals("/text()[1]", p.asPath());
    }

    @Test
    public void processingInstructionProducesTargetedPath() {
        ProcessingInstruction instruction = pi("xml-stylesheet", "type='text/xsl'");
        JDOMNodePointer p = pointer(instruction);

        Assert.assertEquals("/processing-instruction('xml-stylesheet')[1]", p.asPath());
    }

    @Test
    public void nonSpecialNodeWithParentDelegatesToParentOnly() {
        Content content = new Text("x");
        JDOMNodePointer parent = pointer(element("root"));
        JDOMNodePointer child = pointer(content);
        setParent(child, parent);

        Assert.assertEquals("root[1]/text()[1]", child.asPath());
    }

    @Test
    public void nullNamespacePrefixDoesNotUseColonOrQName() {
        Element node = new Element("local", Namespace.NO_NAMESPACE);
        JDOMNodePointer p = pointer(node);

        Assert.assertEquals("local[1]", p.asPath());
    }

    @Test
    public void asPathReturnsEmptyStringForUnsupportedNodeTypesWithoutParent() {
        class DummyContent extends Content {
            @Override
            public String getValue() {
                return "";
            }

            @Override
            public Content clone() {
                return this;
            }
        }

        Content dummy = new DummyContent();
        JDOMNodePointer p = pointer(dummy);

        Assert.assertEquals("", p.asPath());
    }
}

