    private static JDOMNodePointer newPointer(NodePointer parent, Object node) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(NodePointer.class, Object.class);
            return c.newInstance(parent, node);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static JDOMNodePointer newPointer(Object node, Locale locale) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(Object.class, Locale.class);
            return c.newInstance(node, locale);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static JDOMNodePointer newPointer(Object node, Locale locale, String id) {
        try {
            Constructor<JDOMNodePointer> c = JDOMNodePointer.class.getConstructor(Object.class, Locale.class, String.class);
            return c.newInstance(node, locale, id);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static String callAsPath(JDOMNodePointer pointer) {
        try {
            Method m = JDOMNodePointer.class.getMethod("asPath");
            return (String) m.invoke(pointer);
        } catch (InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof RuntimeException) {
                throw (RuntimeException) cause;
            }
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            throw new AssertionError(cause);
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    @Test
    public void testIdPathEscapesQuotesInId() {
        Element root = new Element("root");
        JDOMNodePointer pointer = newPointer(root, Locale.ENGLISH, "a'b");
        assertEquals("id('a\\'b')", callAsPath(pointer));
    }

    @Test
    public void testIdPathTakesPrecedenceOverNodeType() {
        ProcessingInstruction pi = new ProcessingInstruction("target", "data");
        JDOMNodePointer pointer = newPointer(pi, Locale.ENGLISH, "abc");
        assertEquals("id('abc')", callAsPath(pointer));
    }

    @Test
    public void testElementWithoutParentProducesEmptyPathForRootElement() {
        Element root = new Element("root");
        JDOMNodePointer pointer = newPointer(root, Locale.ENGLISH);
        assertEquals("", callAsPath(pointer));
    }

    @Test
    public void testElementWithParentAndNoNamespaceProducesIndexedQNamePath() {
        Element parentElement = new Element("parent");
        Document doc = new Document(parentElement);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child");
        parentElement.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
        String path = callAsPath(childPointer);

        assertNotNull(path);
        assertTrue(path.startsWith("/"));
        assertTrue(path.contains("child["));
        assertTrue(path.endsWith("]"));
    }

    @Test
    public void testElementWithNamespaceAndKnownPrefixUsesPrefixedQName() {
        Namespace ns = Namespace.getNamespace("p", "urn:test");
        Element parent = new Element("parent");
        Document doc = new Document(parent);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child", ns);
        parent.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
        String path = callAsPath(childPointer);

        assertEquals("/p:child[1]", path);
    }

    @Test
    public void testElementWithNamespaceAndUnknownPrefixFallsBackToNodeTest() {
        Namespace ns = Namespace.getNamespace("urn:test");
        Element parent = new Element("parent");
        Document doc = new Document(parent);
        JDOMNodePointer parentPointer = newPointer(doc, Locale.ENGLISH);

        Element child = new Element("child", ns);
        parent.addContent(child);

        JDOMNodePointer childPointer = newPointer(parentPointer, child);
