package org.apache.commons.jxpath.ri.compiler;

import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.Test;

import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class ComputeTests {

    @Test
    public void computeDelegatesToEvalStepsWithInitialContextForAbsolutePath() {
        RecordingLocationPath path = new RecordingLocationPath(true);
        DummyEvalContext context = new DummyEvalContext();

        Object result = path.compute(context);

        assertSame(path.expectedResult, result);
        assertSame(context, path.originalContext);
        assertTrue(path.capturedContext != null);
        assertTrue(path.capturedContext instanceof InitialContext);
    }

    @Test
    public void computeDelegatesToEvalStepsWithInitialContextForRelativePath() {
        RecordingLocationPath path = new RecordingLocationPath(false);
        DummyEvalContext context = new DummyEvalContext();

        Object result = path.compute(context);

        assertSame(path.expectedResult, result);
        assertSame(context, path.originalContext);
        assertTrue(path.capturedContext != null);
        assertTrue(path.capturedContext instanceof InitialContext);
    }

    @Test
    public void computeCreatesFreshInitialContextEachTime() {
        RecordingLocationPath path = new RecordingLocationPath(true);
        DummyEvalContext context = new DummyEvalContext();

        path.compute(context);
        EvalContext first = path.capturedContext;

        path.compute(context);
        EvalContext second = path.capturedContext;

        assertTrue(first != null);
        assertTrue(second != null);
        assertTrue(first != second);
        assertTrue(first instanceof InitialContext);
        assertTrue(second instanceof InitialContext);
    }

    @Test
    public void computeRejectsNullContext() {
        RecordingLocationPath path = new RecordingLocationPath(true);
        try {
            path.compute(null);
            fail("Expected a failure for null context");
        } catch (RuntimeException ex) {
            assertTrue(ex instanceof NullPointerException
                    || ex.getClass().getName().contains("JXPath")
                    || ex.getClass().getName().contains("Runtime"));
        } catch (Error err) {
            throw err;
        }
    }

    @Test
    public void computeDoesNotBypassEvalStepsForAbsoluteOrRelativePaths() {
        RecordingLocationPath absolutePath = new RecordingLocationPath(true);
        RecordingLocationPath relativePath = new RecordingLocationPath(false);
        DummyEvalContext context = new DummyEvalContext();

        absolutePath.compute(context);
        relativePath.compute(context);

        assertTrue(absolutePath.evalStepsCalls == 1);
        assertTrue(relativePath.evalStepsCalls == 1);
        assertTrue(absolutePath.capturedContext instanceof InitialContext);
        assertTrue(relativePath.capturedContext instanceof InitialContext);
    }

    private static final class RecordingLocationPath extends LocationPath {
        private final EvalContext expectedResult = new DummyEvalContext();
        private EvalContext capturedContext;
        private EvalContext originalContext;
        private int evalStepsCalls;

        private RecordingLocationPath(boolean absolute) {
            super(absolute, new Step[0]);
        }

        @Override
        protected EvalContext evalSteps(EvalContext context) {
            this.capturedContext = context;
            this.evalStepsCalls++;
            return expectedResult;
        }

        @Override
        public Object compute(EvalContext context) {
            this.originalContext = context;
            return super.compute(context);
        }
    }

    private static final class DummyEvalContext implements EvalContext {
        @Override
        public NodePointer getCurrentNodePointer() {
            return null;
        }

        @Override
        public void setPosition(int position) {
        }

        @Override
        public int getPosition() {
            return 1;
        }

        @Override
        public int getSize() {
            return 1;
        }

        @Override
        public Object getValue() {
            return null;
        }

        @Override
        public Object getNodeSet() {
            return null;
        }

        @Override
        public boolean nextSet() {
            return false;
        }

        @Override
        public boolean nextNode() {
            return false;
        }

        @Override
        public void setCurrentNodePointer(NodePointer pointer) {
        }

        @Override
        public EvalContext getRootContext() {
            return this;
        }

        @Override
        public boolean isChildAxis() {
            return false;
        }

        @Override
        public void reset() {
        }
    }
}

